:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 24px;
  color: var(--accent);
  letter-spacing: 0.5px;
}

.circle-container {
  display: flex;
  justify-content: center;
  margin-bottom: 24px;
}

canvas {
  width: 100%;
  max-width: 300px;
  height: auto;
  aspect-ratio: 1;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
}

.phase-label {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--text);
  min-height: 2.5rem;
}

.cycle-count {
  font-size: 1.125rem;
  color: var(--text-muted);
  margin-bottom: 24px;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 28px;
  border: 2px solid transparent;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, border-color 0.2s;
  background: var(--primary);
  color: var(--text);
}

.btn:hover:not(:disabled) {
  background: var(--accent);
  border-color: var(--accent);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: scale(0.96);
  background: var(--accent);
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

@media (max-width: 360px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    padding: 10px 20px;
    font-size: 0.9375rem;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('breathingCanvas');
  const ctx = canvas.getContext('2d');
  const phaseLabel = document.getElementById('phaseLabel');
  const cycleCountEl = document.getElementById('cycleCount');
  const startBtn = document.getElementById('startBtn');
  const stopBtn = document.getElementById('stopBtn');

  const PHASE_DURATION = 4000; // 4 seconds
  const BASE_RADIUS = 20;
  const MAX_RADIUS = 120;
  const PIXEL_SIZE = 10;
  const CENTER = 150; // canvas is 300x300

  let animationId = null;
  let startTime = null;
  let running = false;
  let currentPhase = 'inhale'; // 'inhale' or 'exhale'
  let cycleCount = 0;

  function drawCircle(radius) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#e94560';

    const steps = Math.ceil(radius / PIXEL_SIZE);
    const offset = PIXEL_SIZE / 2;

    for (let y = -steps; y <= steps; y++) {
      for (let x = -steps; x <= steps; x++) {
        const dx = x * PIXEL_SIZE;
        const dy = y * PIXEL_SIZE;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist <= radius) {
          ctx.fillRect(
            Math.floor(CENTER + dx - offset),
            Math.floor(CENTER + dy - offset),
            PIXEL_SIZE,
            PIXEL_SIZE
          );
        }
      }
    }
  }

  function update(timestamp) {
    if (!running) return;
    if (startTime === null) startTime = timestamp;

    const elapsed = timestamp - startTime;
    const phaseProgress = Math.min(elapsed / PHASE_DURATION, 1);

    let radius;
    if (currentPhase === 'inhale') {
      radius = BASE_RADIUS + (MAX_RADIUS - BASE_RADIUS) * phaseProgress;
    } else {
      radius = MAX_RADIUS - (MAX_RADIUS - BASE_RADIUS) * phaseProgress;
    }

    drawCircle(radius);

    if (elapsed >= PHASE_DURATION) {
      if (currentPhase === 'inhale') {
        currentPhase = 'exhale';
        phaseLabel.textContent = 'Exhale';
      } else {
        currentPhase = 'inhale';
        cycleCount++;
        cycleCountEl.textContent = 'Cycles: ' + cycleCount;
        phaseLabel.textContent = 'Inhale';
      }
      startTime = timestamp;
    }

    animationId = requestAnimationFrame(update);
  }

  function start() {
    if (running) return;
    running = true;
    startTime = null;
    currentPhase = 'inhale';
    phaseLabel.textContent = 'Inhale';
    startBtn.disabled = true;
    stopBtn.disabled = false;
    animationId = requestAnimationFrame(update);
  }

  function stop() {
    running = false;
    if (animationId) {
      cancelAnimationFrame(animationId);
      animationId = null;
    }
    startBtn.disabled = false;
    stopBtn.disabled = true;
    phaseLabel.textContent = 'Press Start';
    drawCircle(BASE_RADIUS);
  }

  startBtn.addEventListener('click', start);
  stopBtn.addEventListener('click', stop);

  // Initial draw
  drawCircle(BASE_RADIUS);
})();
